K, S, P, D = 3, 2, 1, 2

x = torch.randn(B, IC, D_in, H_in, W_in)
m = nn.ConvTranspose3d(IC, OC, K, stride=S, padding=P, dilation=D, bias=False)
w = m.weight  # (IC, OC, K, K, K)
D_out, H_out, W_out = m(x).shape[2], m(x).shape[3], m(x).shape[4]

# Scatter approach (known correct)
out_scatter = torch.zeros(B, OC, D_out, H_out, W_out)
for d_in in range(D_in):
    for h_in in range(H_in):
        for w_in in range(W_in):
            for kd in range(K):
                d_o = d_in * S + kd * D - P
                if not (0 <= d_o < D_out): continue
                for kh in range(K):
                    h_o = h_in * S + kh * D - P
                    if not (0 <= h_o < H_out): continue
                    for kw in range(K):
                        w_o = w_in * S + kw * D - P
                        if not (0 <= w_o < W_out): continue
                        for oc in range(OC):
                            for ic in range(IC):
                                out_scatter[0, oc, d_o, h_o, w_o] += x[0, ic, d_in, h_in, w_in] * w[ic, oc, kd, kh, kw]

# Gather approach (my kernel)
